class QueueUsingStacks:
    def __init__(self):
        self.in_stack = []
        self.out_stack = []

    def enqueue(self, item):
        """Adds an item to the rear of the queue."""
        self.in_stack.append(item)

    def dequeue(self):
        """Removes and returns the item at the front of the queue.
        Returns None if the queue is empty.
        """
        if not self.out_stack:
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())
        if not self.out_stack:
            return None  # Queue is empty
        return self.out_stack.pop()

    def peek(self):
        """Returns the item at the front of the queue without removing it.
        Returns None if the queue is empty.
        """
        if not self.out_stack:
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())
        if not self.out_stack:
            return None
        return self.out_stack[-1]

    def is_empty(self):
        """Returns True if the queue is empty, False otherwise."""
        return not self.in_stack and not self.out_stack

    def size(self):
        """Returns the number of items in the queue."""
        return len(self.in_stack) + len(self.out_stack)


if __name__ == '__main__':
    queue = QueueUsingStacks()
    queue.enqueue(1)
    queue.enqueue(2)
    queue.enqueue(3)

    print("Queue size:", queue.size())  # Output: Queue size: 3
    print("Peek:", queue.peek()) # Output: Peek: 1
    print("Dequeue:", queue.dequeue()) # Output: Dequeue: 1
    print("Queue size:", queue.size())  # Output: Queue size: 2
    print("Dequeue:", queue.dequeue()) # Output: Dequeue: 2
    print("Dequeue:", queue.dequeue()) # Output: Dequeue: 3
    print("Dequeue:", queue.dequeue()) # Output: Dequeue: None
    print("Is empty:", queue.is_empty()) # Output: Is empty: True
